WHERE a.place_id = #{placeId} AND a.status = 1
ORDER BY a.start_time ASC
LIMIT #{limit}


WHERE a.place_id = #{placeId}
  AND a.status = 1
  AND a.end_time >= NOW()
ORDER BY a.start_time ASC
LIMIT #{limit}


WHERE a.creator_id = #{userId}
   OR EXISTS (
       SELECT 1 FROM activity_member m4
       WHERE m4.activity_id = a.id AND m4.user_id = #{userId}
   )
ORDER BY a.start_time DESC
LIMIT #{limit}

